diff --git a/rich/cells.py b/rich/cells.py
index 15fe7b65..439ef254 100644
--- a/rich/cells.py
+++ b/rich/cells.py
@@ -140,7 +140,7 @@ def _cell_len(text: str, unicode_version: str) -> int:
     for character in iter_characters:
         if character in SPECIAL:
             if character == "\u200d":
-                next(iter_characters)
+                next(iter_characters, None)
             elif last_measured_character:
                 total_width += last_measured_character in cell_table.narrow_to_wide
                 last_measured_character = None
@@ -177,7 +177,7 @@ def split_graphemes(
         if (character := text[index]) in SPECIAL:
             if character == "\u200d":
                 # zero width joiner
-                index += 2
+                index = min(index + 2, codepoint_count)
                 if spans:
                     start, _end, cell_length = spans[-1]
                     spans[-1] = (start, index, cell_length)

